MATCH (tank:PlantItem {tag: 'TK-101'})-[:line_to]-(v:Valve)<-[:control]-(act:PlantItem)<-[:send_signal_to*1..]-(lc:ProcessControlFunction)
RETURN DISTINCT lc.loop_tag AS tag
ORDER BY tag;

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'HS-1001'})-[:send_signal_to*1..]->(actuator:ActuatingFunction)-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'LAL-1015'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(t:PlantItem {tag: 'TK-102'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'P-101A'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH (a)-[:line_to*1..]->(b)
         WHERE NOT EXISTS {
           MATCH (a)-[:line_to*1..]->(:PlantItem {tag: 'BFV-1001'})-[:line_to*1..]->(b)
         }
       } AS can_flow_without_bfv1001

MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'P-101B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-101A'})-[:measured_by]->(i:ProcessInstrumentationFunction)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'P-101A'})
RETURN EXISTS {
  MATCH (a)((n:PlantItem)-[:line_to]->(m:PlantItem) WHERE n.tag <> 'BFV-1001' AND m.tag <> 'BFV-1001')+(b)
} AS reachable

MATCH (source:PlantItem {no_inflow: true})-[:line_to*1..]->(target:PlantItem {tag: 'P-101A'})
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'P-101B'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*0..]->(h:ProcessInstrumentationFunction {loop_tag: 'LI-1013'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'TK-102'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:NeedleValve {unit_id: '1'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(t:PlantItem {tag: 'TK-101'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-101B'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-1002'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:ButterflyValve {unit_id: '1'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:ProcessInstrumentationFunction)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LAL-1019'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'CHV-1001'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) | n.tag] AS tags;
